#!/usr/bin/env python3
import csv
import json
from pathlib import Path

ROOT = Path('/root')

PANEL_MANIFEST = ROOT / 'panel_manifest.json'
SHIPPER_COST = ROOT / 'shipper_cost.csv'
CONTRACT_TERMS = ROOT / 'contract_terms.csv'
NETWORK_ADJUSTMENTS = ROOT / 'network_adjustments.csv'
LAB_CAPACITY_OVERRIDES = ROOT / 'lab_capacity_overrides.csv'
HOLDOUTS = ROOT / 'holdouts.json'
REPORT_TEMPLATE = ROOT / 'report_template.json'
REPORT_OUT = ROOT / 'diagpanel_policy_report.json'
SUMMARY_OUT = ROOT / 'diagpanel_policy_summary.md'

RUNS_PER_YEAR_14_DAY = 26
RUNS_PER_YEAR_28_DAY = 13
DECISION_THRESHOLD_USD = 6000


def load_json(path):
    with path.open('r', encoding='utf-8') as f:
        return json.load(f)


def load_csv(path):
    with path.open('r', encoding='utf-8', newline='') as f:
        return list(csv.DictReader(f))


def as_float(value, default=0.0):
    if value is None:
        return default
    text = str(value).strip()
    if text == '':
        return default
    return float(text)


def as_int(value):
    return int(float(str(value).strip()))


def round_currency(value):
    return round(float(value) + 0.0, 2)


def extract_panels(manifest):
    """Accept both the task's expected list and the actual clustered manifest."""
    if isinstance(manifest, list):
        return manifest
    panels = []
    for cluster in manifest.get('service_clusters', []):
        panels.extend(cluster.get('panels', []))
    return panels


def extract_holdouts(holdouts_doc):
    """Accept both the task's expected list and the actual wrapped holdouts file."""
    if isinstance(holdouts_doc, list):
        return holdouts_doc
    return holdouts_doc.get('holdouts', [])


def find_contract(panel, contract_rows):
    labels = {panel.get('panel_name')}
    labels.update(panel.get('alias_labels') or [])
    candidates = [
        row for row in contract_rows
        if row.get('status_flag') == 'current' and row.get('panel_ref') in labels
    ]
    if not candidates:
        raise ValueError(f"No current contract row found for {panel.get('panel_code')}")
    # effective_week values are ISO-like (e.g. 2026-W22), so lexical ordering is correct.
    return max(candidates, key=lambda row: row.get('effective_week', ''))


def find_active_labs(panel, override_rows):
    valid_rows = []
    for row in override_rows:
        if row.get('panel_code') != panel.get('panel_code'):
            continue
        if row.get('approval') != 'approved':
            continue
        rev = str(row.get('rev', '')).strip()
        active_labs = str(row.get('active_labs', '')).strip()
        if rev == '' or active_labs == '':
            continue
        valid_rows.append(row)
    if not valid_rows:
        return int(panel['default_active_labs'])
    best = max(valid_rows, key=lambda row: as_float(row.get('rev')))
    return as_int(best['active_labs'])


def main():
    manifest = load_json(PANEL_MANIFEST)
    holdouts_doc = load_json(HOLDOUTS)
    template = load_json(REPORT_TEMPLATE)
    shipper_rows = load_csv(SHIPPER_COST)
    contract_rows = load_csv(CONTRACT_TERMS)
    network_rows = load_csv(NETWORK_ADJUSTMENTS)
    override_rows = load_csv(LAB_CAPACITY_OVERRIDES)

    panels = extract_panels(manifest)
    excluded_codes = {
        row.get('panel_code')
        for row in extract_holdouts(holdouts_doc)
        if row.get('holdout_state') == 'exclude'
    }

    retained = [
        panel for panel in panels
        if panel.get('analysis_mode') == 'review' and panel.get('panel_code') not in excluded_codes
    ]

    shipper_by_class = {row['shipper_class']: as_float(row['shipper_cost_usd']) for row in shipper_rows}
    network_by_tier = {row['network_tier']: as_float(row['network_adjustment_per_run_per_lab_usd']) for row in network_rows}

    panel_results = []
    for panel in retained:
        contract = find_contract(panel, contract_rows)
        base_payment = as_float(contract['base_payment_per_run_per_lab_usd'])
        network_adjustment = network_by_tier.get(panel.get('network_tier'), 0.0)
        active_labs = find_active_labs(panel, override_rows)
        shipper_cost_per_run = shipper_by_class[panel['shipper_class']]
        total_payment = base_payment + network_adjustment

        reagent_cost_per_1000 = as_float(panel['reagent_cost_per_1000_tests_usd'])
        tests_14 = as_int(panel['tests_per_lab_per_run_14_day'])
        tests_28 = as_int(panel['tests_per_lab_per_run_28_day'])

        annual_revenue_14 = total_payment * active_labs * RUNS_PER_YEAR_14_DAY
        annual_reagent_cost_14 = reagent_cost_per_1000 * active_labs * tests_14 * RUNS_PER_YEAR_14_DAY / 1000
        annual_shipper_cost_14 = shipper_cost_per_run * RUNS_PER_YEAR_14_DAY
        annual_margin_14 = annual_revenue_14 - annual_reagent_cost_14 - annual_shipper_cost_14

        annual_revenue_28 = total_payment * active_labs * RUNS_PER_YEAR_28_DAY
        annual_reagent_cost_28 = reagent_cost_per_1000 * active_labs * tests_28 * RUNS_PER_YEAR_28_DAY / 1000
        annual_shipper_cost_28 = shipper_cost_per_run * RUNS_PER_YEAR_28_DAY
        annual_margin_28 = annual_revenue_28 - annual_reagent_cost_28 - annual_shipper_cost_28

        difference = annual_margin_28 - annual_margin_14

        panel_results.append({
            'panel_code': panel['panel_code'],
            'panel_name': panel['panel_name'],
            'active_labs': active_labs,
            'base_payment_per_run_per_lab_usd': round_currency(base_payment),
            'network_adjustment_per_run_per_lab_usd': round_currency(network_adjustment),
            'total_payment_per_run_per_lab_usd': round_currency(total_payment),
            'reagent_cost_per_1000_tests_usd': round_currency(reagent_cost_per_1000),
            'tests_per_lab_per_run_14_day': tests_14,
            'tests_per_lab_per_run_28_day': tests_28,
            'shipper_cost_per_run_usd': round_currency(shipper_cost_per_run),
            'annual_revenue_14_day_usd': round_currency(annual_revenue_14),
            'annual_reagent_cost_14_day_usd': round_currency(annual_reagent_cost_14),
            'annual_shipper_cost_14_day_usd': round_currency(annual_shipper_cost_14),
            'annual_margin_14_day_usd': round_currency(annual_margin_14),
            'annual_revenue_28_day_usd': round_currency(annual_revenue_28),
            'annual_reagent_cost_28_day_usd': round_currency(annual_reagent_cost_28),
            'annual_shipper_cost_28_day_usd': round_currency(annual_shipper_cost_28),
            'annual_margin_28_day_usd': round_currency(annual_margin_28),
            'difference_28_minus_14_usd': round_currency(difference),
        })

    panel_results.sort(key=lambda row: row['panel_code'])

    total_margin_14 = sum(row['annual_margin_14_day_usd'] for row in panel_results)
    total_margin_28 = sum(row['annual_margin_28_day_usd'] for row in panel_results)
    total_difference = total_margin_28 - total_margin_14
    absolute_difference = abs(total_difference)
    decision = 'adopt_28_day' if absolute_difference < DECISION_THRESHOLD_USD else 'keep_14_day'

    output = {
        'metadata': template['metadata'],
        'audit_notes': template['audit_notes'],
        'analysis': {
            'assumptions': {
                'runs_per_year_14_day': RUNS_PER_YEAR_14_DAY,
                'runs_per_year_28_day': RUNS_PER_YEAR_28_DAY,
                'decision_threshold_usd': round_currency(DECISION_THRESHOLD_USD),
                'shipper_cost_formula': 'shipper_cost_usd * runs_per_year',
                'currency': 'USD',
            },
            'panels': panel_results,
            'totals': {
                'total_margin_14_day_usd': round_currency(total_margin_14),
                'total_margin_28_day_usd': round_currency(total_margin_28),
                'total_difference_28_minus_14_usd': round_currency(total_difference),
                'absolute_difference_usd': round_currency(absolute_difference),
            },
            'recommendation': {
                'decision': decision,
                'justification': (
                    f"Absolute difference is ${absolute_difference:.2f}, compared with the "
                    f"strict less-than threshold of ${DECISION_THRESHOLD_USD:.2f}; final decision: {decision}."
                ),
            },
        },
    }

    with REPORT_OUT.open('w', encoding='utf-8') as f:
        json.dump(output, f, indent=2, ensure_ascii=False)
        f.write('\n')

    summary_lines = [
        f"Total 14-day margin (USD): {total_margin_14:.2f}",
        f"Total 28-day margin (USD): {total_margin_28:.2f}",
        f"Absolute difference (USD): {absolute_difference:.2f}",
        f"Final decision: {decision}",
    ]
    with SUMMARY_OUT.open('w', encoding='utf-8') as f:
        f.write('\n'.join(summary_lines) + '\n')


if __name__ == '__main__':
    main()

